#include <stdio.h>

int is_vowel(char ch) {
    return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
}

int main(void) {
    const char *text = "the quick brown fox";
    int count = 0;
    for (int i = 0; text[i] != '\0'; i++) {
        char ch = text[i];
        if (ch >= 'A' && ch <= 'Z') {
            ch = (char)(ch - 'A' + 'a');
        }
        if (is_vowel(ch)) {
            count++;
        }
    }
    printf("%d\n", count);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    char text[] = "the quick brown fox";
    char *words[16];
    int count = 0;
    char *token = strtok(text, " ");
    while (token != NULL && count < 16) {
        words[count] = token;
        count++;
        token = strtok(NULL, " ");
    }
    for (int i = count - 1; i >= 0; i--) {
        printf("%s", words[i]);
        printf(i > 0 ? " " : "\n");
    }
    return 0;
}

