std::vector<int> sort_values(std::vector<int> items) {
    for (std::size_t i = 0; i < items.size(); ++i) {
        for (std::size_t j = 0; j + 1 < items.size() - i; ++j) {
            if (items[j] > items[j + 1]) {
                int tmp = items[j];
                items[j] = items[j + 1];
                items[j + 1] = tmp;
            }
        }
    }
    return items;
}

