int total(int n)
{
    int sum = 0;
    for (int i = 1; i <= n; i++)
    {
        sum += i;
    }
    return sum;
}

Console.WriteLine(total(5));

using System;
using System.Collections.Generic;

List<long> fib(int n)
{
    var values = new List<long>();
    long a = 0;
    long b = 1;
    for (int i = 0; i < n; i++)
    {
        values.Add(a);
        long next = a + b;
        a = b;
        b = next;
    }
    return values;
}

Console.WriteLine(string.Join(" ", fib(5)));

using System;
using System.Collections.Generic;

bool isPrime(int value)
{
    if (value < 2)
    {
        return false;
    }
