int[] sortValues(int[] items)
{
    int[] values = (int[])items.Clone();
    for (int i = 0; i < values.Length; i++)
    {
        for (int j = 0; j + 1 < values.Length - i; j++)
        {
            if (values[j] > values[j + 1])
            {
                int tmp = values[j];
                values[j] = values[j + 1];
                values[j + 1] = tmp;
            }
        }
    }
    return values;
}

