function primes(n) {
  const found = [];
  for (let value = 2; value <= n; value += 1) {
    let isPrime = true;
    for (let d = 2; d < value; d += 1) {
      if (value % d === 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      found.push(value);
    }
  }
  return found;
}

