    for (value in 1..n) {
        sum += value
    }
    return sum
}

fun main() {
    println(total(5))
}

fun fib(n: Int): List<Int> {
    var a = 0
    var b = 1
    val out = mutableListOf<Int>()
    for (i in 1..n) {
        out.add(a)
        val next = a + b
        a = b
        b = next
    }
    return out
}

fun main() {
    println(fib(5).joinToString(" "))
}

fun isPrime(value: Int): Boolean {
    if (value < 2) {
        return false
    }
    var factor = 2
    while (factor * factor <= value) {
        if (value % factor == 0) {
            return false
        }
        factor += 1
    }
    return true
}

fun main() {
    val found = (2..5).filter { isPrime(it) }
    println(found.joinToString(","))
}

