val VALUES = listOf(5, 3, 9, 1, 7)

fun bubble(values: List<Int>): List<Int> {
    val items = values.toMutableList()
    for (i in items.indices) {
        for (j in 0 until items.size - 1 - i) {
            if (items[j] > items[j + 1]) {
                val swap = items[j]
                items[j] = items[j + 1]
                items[j + 1] = swap
            }
        }
    }
    return items
}

fun main() {
    println(bubble(VALUES).joinToString(","))
}

val VALUES = listOf(5, 3, 9, 1, 7)

fun main() {
    var low = VALUES[0]
    var high = VALUES[0]
    var total = 0
    for (value in VALUES) {
        if (value < low) {
            low = value
        }
        if (value > high) {
            high = value
        }
        total += value
    }
    val mean = total.toDouble() / VALUES.size
    println("$low $high $mean")
}

