fn total(n: u64) -> u64 {
    (1..=n).sum()
}

fn main() {
    println!("{}", total(5));
}

fn fib(n: usize) -> Vec<u64> {
    let mut out = Vec::new();
    let (mut a, mut b) = (0, 1);
    for _ in 0..n {
        out.push(a);
        let next = a + b;
        a = b;
        b = next;
    }
    out
}

fn main() {
    let values = fib(5);
    let text: Vec<String> = values.iter().map(|v| v.to_string()).collect();
    println!("{}", text.join(" "));
}

fn is_prime(n: u64) -> bool {
    if n < 2 {
        return false;
    }
    for p in 2..=((n as f64).sqrt() as u64) {
        if n % p == 0 {
            return false;
        }
    }
    true
}

fn main() {
    let limit = 5;
    let primes: Vec<String> = (2..=limit)
        .filter(|v| is_prime(*v))
        .map(|v| v.to_string())
        .collect();
    println!("{}", primes.join(","));
}

