print(sequence.joined(separator: " "))

func isPrime(_ value: Int) -> Bool {
    if value < 2 {
        return false
    }
    var factor = 2
    while factor * factor <= value {
        if value % factor == 0 {
            return false
        }
        factor += 1
    }
    return true
}

