    let letters: Set<Character> = Set("aeiou")
    var found = 0
    for character in text {
        if letters.contains(character) {
            found += 1
        }
    }
    return found
}

print(vowels(text))

let text = "keep it simple"

func reverseWords(_ text: String) -> String {
    let words = text.split(separator: " ").map { String($0) }
    return words.reversed().joined(separator: " ")
}

print(reverseWords(text))

let values = [5, 3, 9, 1, 7]

func bubble(_ values: [Int]) -> [Int] {
    var items = values
    let count = items.count
    for i in 0..<count {
        for j in 0..<(count - 1 - i) {
            if items[j] > items[j + 1] {
                items.swapAt(j, j + 1)
            }
        }
    }
    return items
}

print(bubble(values).map { String($0) }.joined(separator: ","))

let values = [5, 3, 9, 1, 7]

func stats(_ values: [Int]) -> (Int, Int, Double) {
    let low = values.min() ?? 0
    let high = values.max() ?? 0
    let total = values.reduce(0, +)
    return (low, high, Double(total) / Double(values.count))
}

let (low, high, mean) = stats(values)
print(low, high, mean)

