function fib(n: number): number[] {
  const out: number[] = [];
  let a: number = 0;
  let b: number = 1;
  for (let i: number = 0; i < n; i += 1) {
    out.push(a);
    const next: number = a + b;
    a = b;
    b = next;
  }
  return out;
}

console.log(fib(5).join(' '));

