function primes(n: number): number[] {
  const found: number[] = [];
  for (let value: number = 2; value <= n; value += 1) {
    let isPrime: boolean = true;
    for (let d: number = 2; d < value; d += 1) {
      if (value % d === 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      found.push(value);
    }
  }
  return found;
}

