const VALUES: number[] = [5, 3, 9, 1, 7];

function bubble(values: number[]): number[] {
  const items: number[] = values.slice();
  for (let i: number = 0; i < items.length; i += 1) {
    for (let j: number = 0; j < items.length - 1 - i; j += 1) {
      if (items[j] > items[j + 1]) {
        const held: number = items[j];
        items[j] = items[j + 1];
        items[j + 1] = held;
      }
    }
  }
  return items;
}

