const VALUES: number[] = [5, 3, 9, 1, 7];

function stats(values: number[]): number[] {
  let low: number = values[0];
  let high: number = values[0];
  let sum: number = 0;
  for (const value of values) {
    if (value < low) {
      low = value;
    }
    if (value > high) {
      high = value;
    }
    sum += value;
  }
  return [low, high, sum / values.length];
}

